+import { logger } from '../lib/logger';
+
+export enum ThreatCategory {
+  PROMPT_INJECTION = 'prompt_injection',
+  ROLE_HIJACKING = 'role_hijacking',
+  CONTEXT_MANIPULATION = 'context_manipulation',
+  SAFE = 'safe',
+}
+
+/**
+ * Moderates user comments for prompt injection and role hijacking attempts.
+ * This prevents adversarial users from manipulating the AI system
+ * by embedding instructions like "ignore previous" or "you are now" in comments.
+ */
+export function moderateComment(comment: string): ThreatCategory {
+  const normalized = comment.toLowerCase().trim();
+
+  // Check for prompt injection patterns
+  if (/ignore\s+previous/i.test(normalized)) {
+    logger.warn('Prompt injection attempt detected in comment', { preview: normalized.slice(0, 80) });
+    return ThreatCategory.PROMPT_INJECTION;
+  }
+
+  return ThreatCategory.SAFE;
+}
